<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/src/Database.php';
require_once dirname(__DIR__).'/src/AdultParticipantService.php';
require_once dirname(__DIR__).'/src/CastingService.php';
require_once dirname(__DIR__).'/src/CastingOfferService.php';
require_once dirname(__DIR__).'/src/ProductionPeopleExperience.php';
require_once dirname(__DIR__).'/src/CommunicationExperience.php';
require_once dirname(__DIR__).'/src/StudentProfileService.php';
require_once dirname(__DIR__).'/src/PlaybillEnhancementService.php';
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='rc1-test'||getenv('DB_HOST')!=='127.0.0.1'||!preg_match('/^ctsmd_rc1_[a-z0-9_]{1,40}$/',(string)getenv('DB_DATABASE')))throw new RuntimeException('Explicit disposable loopback rc1-test schema required.');
$db=Database::connect(dirname(__DIR__));$checks=0;$ids=[];$productions=[];$suffix=bin2hex(random_bytes(6));
$assert=static function(bool $ok,string $label)use(&$checks):void{if(!$ok)throw new RuntimeException($label);$checks++;echo 'PASS '.$label."\n";};
$denied=static function(callable $fn,string $label)use($assert):void{$blocked=false;try{$fn();}catch(RuntimeException){$blocked=true;}$assert($blocked,$label);};
$person=static function(string $role,string $dob)use($db,&$ids,$suffix):int{
    $db->prepare("INSERT INTO users(first_name,last_name,email,initials,display_role,account_status,active,organization_membership_status,date_of_birth) VALUES('AdultTest',?,?,'AT',?,'active',1,'approved',?)")->execute([$role,$role.'.'.count($ids).'.'.$suffix.'@rc1.invalid',$role,$dob]);$id=(int)$db->lastInsertId();$ids[]=$id;
    $db->prepare('INSERT INTO auth_user_roles(user_id,role_id) SELECT ?,id FROM auth_roles WHERE code=?')->execute([$id,$role]);return $id;
};
try{
    $admin=$person('administrator','1980-01-01');$adult=$person('member','1990-01-01');$student=$person('student','2017-01-01');$volunteer=$person('volunteer','1990-01-01');$staff=$person('production_staff','1980-01-01');
    foreach(['mixed','adults'] as $category){$db->prepare("INSERT INTO productions(title,is_active,status,lifecycle_stage,participant_category,student_minimum_age,participant_eligibility_date) VALUES(?,1,'planning','planning',?,10,'2026-10-28')")->execute(['Adult test '.$suffix,$category]);$productions[]=(int)$db->lastInsertId();}
    [$mixed,$adultOnly]=$productions;
    $denied(fn()=>ProductionParticipantEligibility::saveSettings($db,$mixed,$adult,['participant_category'=>'mixed']),'Settings forged actor denied');
    $denied(fn()=>ProductionParticipantEligibility::saveSettings($db,$mixed,$admin,['participant_category'=>'mixed','student_minimum_age'=>'9']),'Restricted ages require explicit date');
    ProductionParticipantEligibility::saveSettings($db,$mixed,$admin,['participant_category'=>'mixed','student_minimum_age'=>'10','participant_eligibility_date'=>'2026-10-28']);
    $assert((int)$db->query('SELECT student_minimum_age FROM productions WHERE id='.$mixed)->fetchColumn()===10,'Participation settings persisted');
    $denied(fn()=>AdultParticipantService::classify($db,$adult,$adult,true,'Self approval'),'Self classification denied');
    AdultParticipantService::classify($db,$admin,$adult,true,'Reviewed independent Adult participation');
    $assert(ProductionParticipantEligibility::forUser($db,$mixed,$adult)['eligible'],'Reviewed Adult eligible');
    $assert(!in_array('production.manage',Auth::permissions($db,$adult),true),'Adult gains no management authority');
    $denied(fn()=>AdultParticipantService::classify($db,$admin,$student,true,'DOB bypass'),'Student classification bypass denied');
    $assert(ProductionParticipantEligibility::forUser($db,$mixed,$student)['status']==='below_minimum_age','Stored Student DOB enforced');
    $denied(fn()=>ProductionParticipantEligibility::exception($db,$mixed,$student,$adult,'Forged approval'),'Forged exception denied');
    $denied(fn()=>ProductionParticipantEligibility::exception($db,$mixed,$student,$staff,'Unassigned staff'),'Cross-production staff exception denied');
    ProductionParticipantEligibility::exception($db,$mixed,$student,$admin,'Reviewed age exception');
    $assert(ProductionParticipantEligibility::forUser($db,$mixed,$student)['status']==='authorized_exception','Audited exception used');
    ProductionParticipantEligibility::exception($db,$adultOnly,$student,$admin,'Age only');
    $assert(ProductionParticipantEligibility::forUser($db,$adultOnly,$student)['status']==='wrong_participant_category','Age exception cannot waive Adults-only');
    ProductionParticipantEligibility::exception($db,$mixed,$student,$admin,'Exception withdrawn',true);
    $assert(!ProductionParticipantEligibility::forUser($db,$mixed,$student)['eligible'],'Revoked exception rejected');
    $db->prepare('UPDATE users SET date_of_birth=? WHERE id=?')->execute(['1980-01-01',$student]);
    $assert(IdentityRolePolicy::isStudent($db,$student),'DOB edit preserves Student');
    $denied(fn()=>IdentityRolePolicy::assertRoleSelection($db,$student,[]),'Generic role edit cannot remove safeguarding');
    $db->prepare("INSERT INTO family_relationships(guardian_user_id,student_user_id,relationship_type,status) VALUES(?,?,'guardian','active'),(?,?,'guardian','active')")->execute([$adult,$student,$admin,$student]);
    $db->prepare("INSERT INTO production_memberships(production_id,user_id,audience_type,status) VALUES(?,?,'staff','active'),(?,?,'guardian','active')")->execute([$mixed,$admin,$mixed,$adult]);
    $record=CastingService::add($db,$mixed,$admin,$adult);
    CastingService::update($db,$mixed,$admin,$record,['casting_status'=>'offered','role_title'=>'Scrooge']);
    $offer=CastingOfferService::issue($db,$mixed,$record,$admin);
    $assert($offer===CastingOfferService::issue($db,$mixed,$record,$admin),'Repeated issue is idempotent');
    $denied(fn()=>CastingOfferService::respond($db,$volunteer,$offer,'accepted',''),'Unrelated offer response denied');
    CastingOfferService::respond($db,$adult,$offer,'accepted','');
    $assert((int)$db->query("SELECT COUNT(*) FROM production_memberships WHERE production_id=$mixed AND user_id=$adult AND audience_type='adult' AND status='active'")->fetchColumn()===1,'Adult self acceptance enrolls Adult');
    $assert((int)$db->query("SELECT COUNT(*) FROM production_memberships WHERE production_id=$mixed AND user_id=$adult AND audience_type='guardian' AND status='active'")->fetchColumn()===1,'Adult cast membership preserves independent Guardian membership');
    $assert((int)$db->query("SELECT COUNT(*) FROM theatre_history_credits WHERE production_id=$mixed AND user_id=$adult AND role_title='Scrooge'")->fetchColumn()===1,'Adult history credit created');
    $denied(fn()=>CastingOfferService::respond($db,$adult,$offer,'accepted',''),'Repeated acceptance cannot duplicate enrollment');
    ProductionParticipantEligibility::saveSettings($db,$adultOnly,$admin,['participant_category'=>'adults']);
    $second=CastingService::add($db,$adultOnly,$admin,$adult);CastingService::update($db,$adultOnly,$admin,$second,['casting_status'=>'offered','role_title'=>'Crew']);
    CastingOfferService::respond($db,$adult,CastingOfferService::issue($db,$adultOnly,$second,$admin),'accepted','');
    $assert((int)$db->query("SELECT COUNT(*) FROM production_memberships WHERE user_id=$adult AND audience_type='adult' AND status='active'")->fetchColumn()===2,'Independent multi-production participation');
    $studentRecord=CastingService::add($db,$mixed,$admin,$student);CastingService::update($db,$mixed,$admin,$studentRecord,['casting_status'=>'offered','role_title'=>'Tiny Tim']);
    $studentOffer=CastingOfferService::issue($db,$mixed,$studentRecord,$admin);CastingOfferService::respond($db,$adult,$studentOffer,'accepted','');
    $assert((int)$db->query("SELECT COUNT(*) FROM production_memberships WHERE production_id=$mixed AND user_id=$student AND audience_type='student' AND status='active'")->fetchColumn()===1,'Student guardian acceptance enrolls Student');
    $initiator=['id'=>$adult,'roles'=>['member'],'permissions'=>[]];
    $ownThread=CommunicationExperience::mobileCreateConversation($db,$initiator,$student,'Family cast','Guardian-inclusive family conversation');
    $assert(SafeguardedConversationPolicy::canReceiveLive($db,$ownThread,$adult),'Adult guardian retains family context with separate guardian included');
    StudentProfileService::save($db,dirname(__DIR__),$initiator,$adult,['date_of_birth'=>'1990-01-01','short_bio'=>'An independently approved Adult performer.'],[]);
    $assert(StudentProfileService::profile($db,$adult)['short_bio']==='An independently approved Adult performer.','Adult shares reusable performer profile storage');
    $assert(!StudentProfileService::canEdit($db,['id'=>$volunteer,'permissions'=>[],'roles'=>['volunteer']],$adult),'Unrelated person cannot edit Adult profile');
    $db->prepare("INSERT INTO playbills(production_id,status,display_title) VALUES(?,'draft','Adult test Playbill')")->execute([$adultOnly]);$playbill=(int)$db->lastInsertId();
    PlaybillEnhancementService::syncCastProfiles($db,$playbill,$adultOnly,$admin);
    $profileId=(int)$db->query("SELECT id FROM playbill_cast_profiles WHERE playbill_id=$playbill AND user_id=$adult")->fetchColumn();
    $assert($profileId>0,'Playbill sync includes Adult and resolves casting-role join');
    $assert(PlaybillEnhancementService::publicCastProfiles($db,$playbill)===[],'Adult classification does not imply publication consent');
    PlaybillEnhancementService::saveCastProfile($db,dirname(__DIR__),$playbill,$adult,$admin,['display_name'=>'Adult Performer','role_title'=>'Crew','biography'=>'Approved snapshot','visible'=>1],[]);
    $denied(fn()=>PlaybillEnhancementService::decideCastApproval($db,['id'=>$admin,'permissions'=>['people.manage'],'roles'=>['administrator']],$profileId,'approved'),'Staff cannot fabricate Adult publication consent');
    PlaybillEnhancementService::decideCastApproval($db,$initiator,$profileId,'approved');
    $assert(count(PlaybillEnhancementService::publicCastProfiles($db,$playbill))===1,'Adult explicitly approves Playbill snapshot');
    PlaybillEnhancementService::decideCastApproval($db,$initiator,$profileId,'withdrawn');
    PlaybillEnhancementService::syncCastProfiles($db,$playbill,$adultOnly,$admin);
    $assert(PlaybillEnhancementService::publicCastProfiles($db,$playbill)===[],'Resync preserves consent withdrawal');
    $messageStudent=$person('student','2015-01-01');
    $db->prepare("INSERT INTO family_relationships(guardian_user_id,student_user_id,relationship_type,status) VALUES(?,?,'guardian','active')")->execute([$admin,$messageStudent]);
    $db->prepare("INSERT INTO production_memberships(production_id,user_id,audience_type,status) VALUES(?,?,'student','active')")->execute([$mixed,$messageStudent]);
    $thread=CommunicationExperience::mobileCreateConversation($db,$initiator,$messageStudent,'Mixed cast','Hello from your cast mate');
    $assert(SafeguardedConversationPolicy::canReceiveLive($db,$thread,$admin),'Mixed conversation includes Student guardian');
    $assert(SafeguardedConversationPolicy::canReceiveLive($db,$thread,$adult),'Authorized Adult receives mixed conversation');
    $assert($db->query('SELECT conversation_type FROM conversations WHERE id='.$thread)->fetchColumn()==='safeguarded','Adult to Student uses safeguarded thread');
    $direct=CommunicationExperience::mobileCreateConversation($db,$initiator,$volunteer,'Adult conversation','Ordinary conversation');
    $assert($db->query('SELECT conversation_type FROM conversations WHERE id='.$direct)->fetchColumn()==='direct','Adult to Adult ordinary conversation');
    $denied(fn()=>$db->prepare("INSERT INTO conversation_participants(conversation_id,user_id,participant_role,guardian_required) VALUES(?,?,'student',0)")->execute([$direct,$student]),'Student cannot inherit Adult direct history');
    $membershipId=(int)$db->query("SELECT id FROM production_memberships WHERE production_id=$mixed AND user_id=$adult AND audience_type='adult'")->fetchColumn();
    (new ReflectionMethod(ProductionPeopleExperience::class,'deactivateMember'))->invoke(null,$db,['id'=>$admin],$mixed,$membershipId);
    $assert($db->query('SELECT casting_status FROM production_casting_records WHERE id='.$record)->fetchColumn()==='withdrawn','Roster removal retains withdrawn casting history');
    $assert($db->query('SELECT status FROM production_cast_offers WHERE id='.$offer)->fetchColumn()==='accepted','Roster removal preserves accepted offer history');
    $assert((int)$db->query("SELECT COUNT(*) FROM production_memberships WHERE production_id=$adultOnly AND user_id=$adult AND audience_type='adult' AND status='active'")->fetchColumn()===1,'Roster removal leaves other production intact');
    $assert((int)$db->query("SELECT COUNT(*) FROM family_relationships WHERE guardian_user_id=$adult AND student_user_id=$student AND status='active'")->fetchColumn()===1,'Cast removal preserves family relationship');
    $denied(fn()=>SafeguardedConversationPolicy::enforceForSend($db,$thread,$adult),'Removed Adult cannot continue production-based Student conversation');
    $db->prepare("UPDATE productions SET lifecycle_stage='archived',status='archived' WHERE id=?")->execute([$adultOnly]);
    $assert(!ProductionParticipantEligibility::forUser($db,$adultOnly,$adult)['eligible'],'Archived production denied');
    $db->prepare("UPDATE users SET account_status='disabled' WHERE id=?")->execute([$adult]);
    $assert(!ProductionParticipantEligibility::forUser($db,$mixed,$adult)['eligible'],'Disabled Adult denied');
    $assert((int)$db->query("SELECT COUNT(*) FROM audit_events WHERE event_type='participation.adult_classification' AND subject_id=".$adult)->fetchColumn()===1,'Classification audit retained');
    echo "PASS $checks migrated MySQL participation assertions; synthetic records only.\n";
}finally{
    if($db->inTransaction())$db->rollBack();
    foreach($ids as $id)if(IdentityRolePolicy::isStudent($db,$id))$db->prepare("UPDATE users SET account_status='disabled' WHERE id=?")->execute([$id]);
    foreach($ids as $id)$db->prepare("UPDATE users SET account_status='disabled' WHERE id=?")->execute([$id]);
    foreach($productions as $id)$db->prepare("UPDATE productions SET lifecycle_stage='archived',status='archived',is_active=0 WHERE id=?")->execute([$id]);
}
